<h1>🛒 超级商店</h1>
<p><strong>超级商店</strong> 是一个基于 KubeJS 的首选商店系统，适用于需要超越基础买卖菜单的整合包。</p>
<p>创建整洁的商店类别，注册自定义条目，将物品锁在进度之后，根据购买量调整价格，并运行具有自定义效果的限时闪购。对于小型商店保持简单，但为整合包制作者提供足够的控制权来构建完整的经济系统、季节性活动和依赖进度的游戏玩法。</p>
<h2>✨ 功能特性</h2>
<ul>
<li>📦 通过 KubeJS 完全注册<strong>买卖条目</strong></li>
<li>🗂️ 使用图标、排序和可见性创建自定义<strong>类别</strong></li>
<li>💰 设置每个条目的<strong>价格、数量、NBT、悬停主题和顺序</strong></li>
<li>📈 添加<strong>购买限制</strong>和<strong>动态定价</strong></li>
<li>🔒 通过<strong>玩家进度检查</strong>限制条目访问</li>
<li>⚡ 在类别或标记的商店条目上运行<strong>闪购活动</strong></li>
<li>🧩 通过<strong>KubeJS 事件</strong>挂钩商店活动</li>
<li>🎯 适用于教程、 loot 箱、资源交换、修饰符和限时活动</li>
</ul>
<h2>🧪 简单的 KubeJS 示例</h2>
<h3>📁 创建类别</h3>
<pre><code>ServerEvents.superiorShopCategories(event =&gt; {
  event.category('starter', cat =&gt; {
    cat.title('初始补给') // 商店中显示的名称
    cat.icon('minecraft:emerald') // 类别使用的图标
    cat.order(0) // 数值越小越靠前
    cat.hidden(false) // 设为 true 则隐藏该类别
  })
})
</code></pre>
<h3>🛍️ 添加基本买卖条目</h3>
<pre><code>ServerEvents.superiorShopItems(event =&gt; {
  const starter = event.category('starter') // 通过 id 获取类别

  starter.item('minecraft:bread', 'buy', 5) // 物品id、方向、基础价格
    .hoverTheme('light_green') // 可选的条目颜色/主题
    .order(0) // 类别内的可选排序位置

  starter.item('minecraft:rotten_flesh', 'sell', 2) // 卖入示例
    .hoverTheme('dark_red')
    .order(1)
})
</code></pre>
<h3>📈 添加带动态价格的限购物品</h3>
<pre><code>ServerEvents.superiorShopItems(event =&gt; {
  event.category('starter')
    .item('minecraft:golden_apple', 'buy', 25)
    .limit(5) // 此条目每人仅可购买5次
    .scalingMultiply(1.5) // 每次购买后价格上涨1.5倍
    .scalingRound('ceil') // 向上取整新价格
    .scalingMax(200) // 价格不超过200
    .hoverTheme('gold')
})
</code></pre>
<h3>🔒 隐藏条目直到玩家解锁</h3>
<pre><code>ServerEvents.superiorShopItems(event =&gt; {
  event.category('starter')
    .item('minecraft:elytra', 'buy', 2500)
    .visibleIf(player =&gt; player.persistentData.getBoolean('killed_dragon'))
    // 只有当这个玩家数据标志为true时才显示
    .hoverTheme('light_blue')
})
</code></pre>
<h3>⚡ 标记条目并运行闪购</h3>
<pre><code>ServerEvents.superiorShopItems(event =&gt; {
  event.category('starter')
    .item('minecraft:iron_pickaxe', 'buy', 40)
    .entryTag('mining_fever') // 标签让闪购能针对此条目
})

SuperiorShop.startSale('mining_fever', 120, sale =&gt; { // 120是事件持续秒数
  sale.message('挖矿狂热：标记商品2分钟半价！')
  sale.affectEntryTag('mining_fever', rule => rule.mulBuyPrice(0.5))
  // 所有带有此标签的条目在活动期间享受折扣
})
</code></pre>
<h3>🎁 响应购买或售出</h3>
<pre><code>ServerEvents.superiorShopBuyEntry(event =&gt; {
  // 当玩家从商店购买时触发
  event.player.tell(`你花费了${event.totalPrice}商店货币。`)
})

ServerEvents.superiorShopSellEntry(event =&gt; {
  // 当玩家向商店出售时触发
  if (event.totalPrice >= 100) {
    // 示例：大额交易给予小额奖励
    Utils.server.runCommandSilent(`/superior_shop add ${event.player.username} 10`)
  }
})
</code></pre>
<h3>🧱 数据驱动商店示例</h3>
<pre><code>// 所有类别定义在一个对象中，便于编辑商店布局
const SHOP_CATEGORIES = {
  starter_supplies: {
    title: '初始补给',
    icon: 'minecraft:bread',
    order: 0,
    hidden: false,
  },

  mob_drops: {
    title: '怪物掉落',
    icon: 'minecraft:bone',
    order: 1,
    hidden: false,
  },

  special_offers: {
    title: '特别优惠',
    icon: 'minecraft:golden_apple',
    order: 2,
    hidden: false,
  },
}

// 按组归类物品并通过循环注册
const SHOP_ITEMS = {
  starter_supplies: {
    defaults: {
      side: 'buy', // 该类别大部分是买入条目
      hoverTheme: 'light_green',
    },
    entries: [
      {
        item: 'minecraft:bread',
        price: 5,
        quantity: 8, // 购买此条目获得8个面包
      },
      {
        item: 'minecraft:torch',
        price: 3,
        quantity: 16,
      },
      {
        item: 'minecraft:iron_pickaxe',
        price: 40,
        entryTag: 'starter_sale', // 允许闪购针对此条目
      },
    ],
  },

  mob_drops: {
    defaults: {
      side: 'sell', // 该类别大部分是卖出条目
      hoverTheme: 'dark_red',
    },
    entries: [
      {
        item: 'minecraft:rotten_flesh',
        price: 2,
      },
      {
        item: 'minecraft:bone',
        price: 3,
      },
      {
        item: 'minecraft:string',
        price: 4,
      },
    ],
  },

  special_offers: {
    defaults: {
      side: 'buy',
      hoverTheme: 'gold',
    },
    entries: [
      {
        item: 'minecraft:golden_apple',
        price: 25,
        id: 'special_golden_apple', // 此商店条目的自定义id
        limit: 5, // 限购5次
        scalingPrice: {
          mode: 'multiply',
          factor: 1.5, // 每次购买后价格上涨1.5倍
          round: 'ceil',
          max: 200, // 价格上限200
        },
      },
      {
        item: 'minecraft:enchanted_book',
        price: 150,
        nbt: '{StoredEnchantments:[{id:"minecraft:unbreaking",lvl:3s}]}',
        // 出售特定NBT物品的示例
      },
      {
        item: 'minecraft:elytra',
        price: 2500,
        visibleIf: player => player.persistentData.getBoolean('killed_dragon'),
        // 仅在KubeJS其他地方设置此玩家数据标志时显示
      },
    ],
  },
}

ServerEvents.superiorShopCategories(event => {
  Object.entries(SHOP_CATEGORIES).forEach(([id, data] => {
    event.category(id, cat => {
      cat.title(data.title)
      cat.icon(data.icon)
      cat.order(data.order)
      cat.hidden(data.hidden)
    })
  }))
})

function applyShopEntry(builder, entry, index, defaults) {
  const hoverTheme = entry.hoverTheme || defaults.hoverTheme
  const side = entry.side || defaults.side

  if (entry.id) builder.id(entry.id)
  if (entry.nbt) builder.nbt(entry.nbt)
  if (hoverTheme) builder.hoverTheme(hoverTheme)
  if (entry.entryTag) builder.entryTag(entry.entryTag)
  if (entry.quantity !== undefined) builder.quantity(entry.quantity)
  if (entry.limit !== undefined) builder.limit(entry.limit)

  if (entry.scalingPrice) {
    const scaling = entry.scalingPrice
    if (scaling.mode === 'multiply') builder.scalingMultiply(scaling.factor)
    if (scaling.round) builder.scalingRound(scaling.round)
    if (scaling.max !== undefined) builder.scalingMax(scaling.max)
  }

  if (entry.visibleIf) builder.visibleIf(entry.visibleIf)

  builder.order(entry.order || index)
}

ServerEvents.superiorShopItems(event => {
  Object.entries(SHOP_ITEMS).forEach(([categoryId, categoryData] => {
    const category = event.category(categoryId)
    const defaults = categoryData.defaults || {}

    categoryData.entries.forEach((entry, index) => {
      const side = entry.side || defaults.side || 'buy'
      const builder = category.item(entry.item, side, entry.price)
      applyShopEntry(builder, entry, index, defaults)
    })
  }))
})
</code></pre>
